cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math_constants.h>
#include <ATen/cuda/CUDAContext.h>

// Max reduction over the middle dimension of a contiguous 3D tensor
// of shape (outer, reduce, inner). Output shape: (outer, inner).
// Each thread computes one output element; threads with consecutive
// inner indices read consecutive memory, so loads are fully coalesced.
__global__ void max_reduce_middle_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int outer,
    const int reduce,
    const int inner)
{
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int j0 = blockIdx.x * 128 + lane;
    const int b = blockIdx.y;
    if (b >= outer) return;
    __shared__ float partial[8][129];
    float m0 = -CUDART_INF_F;
    float m1 = -CUDART_INF_F;
    float m2 = -CUDART_INF_F;
    float m3 = -CUDART_INF_F;
    // Bounds handling: hoist the four column predicates and clamp each
    // column address into range so that EVERY block (including the ragged
    // tail block when inner is not a multiple of 128) can run the same
    // unrolled, high-MLP row loop. Out-of-range columns load a valid
    // dummy location (inner-1) and are masked once after the row loops,
    // keeping select instructions out of the hot reduction loop.
    const bool v0 = j0 < inner;
    const bool v1 = j0 + 32 < inner;
    const bool v2 = j0 + 64 < inner;
    const bool v3 = j0 + 96 < inner;
    const int last = inner - 1;
    const int c0 = v0 ? j0        : last;
    const int c1 = v1 ? j0 + 32   : last;
    const int c2 = v2 ? j0 + 64   : last;
    const int c3 = v3 ? j0 + 96   : last;
    const size_t rowbase = (size_t)b * (size_t)reduce * (size_t)inner;
    const float* p0 = x + rowbase + c0;
    const float* p1 = x + rowbase + c1;
    const float* p2 = x + rowbase + c2;
    const float* p3 = x + rowbase + c3;
    const float ninf = -CUDART_INF_F;
    int i = warp;
    const size_t step = (size_t)8 * inner;
    for (; i + 24 < reduce; i += 32) {
        const size_t o0 = (size_t)i * inner;
        const size_t o1 = o0 + step;
        const size_t o2 = o1 + step;
        const size_t o3 = o2 + step;
        m0 = fmaxf(m0, __ldcs(p0 + o0));
        m1 = fmaxf(m1, __ldcs(p1 + o0));
        m2 = fmaxf(m2, __ldcs(p2 + o0));
        m3 = fmaxf(m3, __ldcs(p3 + o0));
        m0 = fmaxf(m0, __ldcs(p0 + o1));
        m1 = fmaxf(m1, __ldcs(p1 + o1));
        m2 = fmaxf(m2, __ldcs(p2 + o1));
        m3 = fmaxf(m3, __ldcs(p3 + o1));
        m0 = fmaxf(m0, __ldcs(p0 + o2));
        m1 = fmaxf(m1, __ldcs(p1 + o2));
        m2 = fmaxf(m2, __ldcs(p2 + o2));
        m3 = fmaxf(m3, __ldcs(p3 + o2));
        m0 = fmaxf(m0, __ldcs(p0 + o3));
        m1 = fmaxf(m1, __ldcs(p1 + o3));
        m2 = fmaxf(m2, __ldcs(p2 + o3));
        m3 = fmaxf(m3, __ldcs(p3 + o3));
    }
    for (; i < reduce; i += 8) {
        const size_t o = (size_t)i * inner;
        m0 = fmaxf(m0, __ldcs(p0 + o));
        m1 = fmaxf(m1, __ldcs(p1 + o));
        m2 = fmaxf(m2, __ldcs(p2 + o));
        m3 = fmaxf(m3, __ldcs(p3 + o));
    }
    if (!v0) m0 = ninf;
    if (!v1) m1 = ninf;
    if (!v2) m2 = ninf;
    if (!v3) m3 = ninf;
    partial[warp][lane]      = m0;
    partial[warp][lane + 32] = m1;
    partial[warp][lane + 64] = m2;
    partial[warp][lane + 96] = m3;
    __syncthreads();
    if (warp == 0) {
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            const int j = j0 + k * 32;
            if (j < inner) {
                float r = partial[0][lane + k * 32];
                #pragma unroll
                for (int w = 1; w < 8; ++w) r = fmaxf(r, partial[w][lane + k * 32]);
                out[(size_t)b * inner + j] = r;
            }
        }
    }
}

// Vectorized variant for the common case where the reduced rows and the
// output rows are 16-byte aligned (inner % 4 == 0). Each lane reduces four
// consecutive float4 column groups; global loads/stores are 128-bit.
__global__ void max_reduce_middle_vec4_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    const int outer,
    const int reduce,
    const int inner)
{
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    const int inner4 = inner >> 2;
    const int g0 = blockIdx.x * 128 + lane;
    const int b = blockIdx.y;
    if (b >= outer) return;
    __shared__ float4 partial4[8][128];
    float4 m0 = make_float4(-CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F);
    float4 m1 = m0;
    float4 m2 = m0;
    float4 m3 = m0;
    const bool v0 = g0 < inner4;
    const bool v1 = g0 + 32 < inner4;
    const bool v2 = g0 + 64 < inner4;
    const bool v3 = g0 + 96 < inner4;
    const int last4 = inner4 - 1;
    const int c0 = (v0 ? g0      : last4) << 2;
    const int c1 = (v1 ? g0 + 32 : last4) << 2;
    const int c2 = (v2 ? g0 + 64 : last4) << 2;
    const int c3 = (v3 ? g0 + 96 : last4) << 2;
    const size_t rowbase = (size_t)b * (size_t)reduce * (size_t)inner;
    const float4* p0 = reinterpret_cast<const float4*>(x + rowbase + c0);
    const float4* p1 = reinterpret_cast<const float4*>(x + rowbase + c1);
    const float4* p2 = reinterpret_cast<const float4*>(x + rowbase + c2);
    const float4* p3 = reinterpret_cast<const float4*>(x + rowbase + c3);
    const float4 ninf4 = make_float4(-CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F, -CUDART_INF_F);
    int i = warp;
    const size_t step4 = (size_t)8 * inner4;
    for (; i + 24 < reduce; i += 32) {
        const size_t o0 = (size_t)i * inner4;
        const size_t o1 = o0 + step4;
        const size_t o2 = o1 + step4;
        const size_t o3 = o2 + step4;
        float4 a;
        a = __ldcs(p0 + o0); m0.x = fmaxf(m0.x, a.x); m0.y = fmaxf(m0.y, a.y); m0.z = fmaxf(m0.z, a.z); m0.w = fmaxf(m0.w, a.w);
        a = __ldcs(p1 + o0); m1.x = fmaxf(m1.x, a.x); m1.y = fmaxf(m1.y, a.y); m1.z = fmaxf(m1.z, a.z); m1.w = fmaxf(m1.w, a.w);
        a = __ldcs(p2 + o0); m2.x = fmaxf(m2.x, a.x); m2.y = fmaxf(m2.y, a.y); m2.z = fmaxf(m2.z, a.z); m2.w = fmaxf(m2.w, a.w);
        a = __ldcs(p3 + o0); m3.x = fmaxf(m3.x, a.x); m3.y = fmaxf(m3.y, a.y); m3.z = fmaxf(m3.z, a.z); m3.w = fmaxf(m3.w, a.w);
        a = __ldcs(p0 + o1); m0.x = fmaxf(m0.x, a.x); m0.y = fmaxf(m0.y, a.y); m0.z = fmaxf(m0.z, a.z); m0.w = fmaxf(m0.w, a.w);
        a = __ldcs(p1 + o1); m1.x = fmaxf(m1.x, a.x); m1.y = fmaxf(m1.y, a.y); m1.z = fmaxf(m1.z, a.z); m1.w = fmaxf(m1.w, a.w);
        a = __ldcs(p2 + o1); m2.x = fmaxf(m2.x, a.x); m2.y = fmaxf(m2.y, a.y); m2.z = fmaxf(m2.z, a.z); m2.w = fmaxf(m2.w, a.w);
        a = __ldcs(p3 + o1); m3.x = fmaxf(m3.x, a.x); m3.y = fmaxf(m3.y, a.y); m3.z = fmaxf(m3.z, a.z); m3.w = fmaxf(m3.w, a.w);
        a = __ldcs(p0 + o2); m0.x = fmaxf(m0.x, a.x); m0.y = fmaxf(m0.y, a.y); m0.z = fmaxf(m0.z, a.z); m0.w = fmaxf(m0.w, a.w);
        a = __ldcs(p1 + o2); m1.x = fmaxf(m1.x, a.x); m1.y = fmaxf(m1.y, a.y); m1.z = fmaxf(m1.z, a.z); m1.w = fmaxf(m1.w, a.w);
        a = __ldcs(p2 + o2); m2.x = fmaxf(m2.x, a.x); m2.y = fmaxf(m2.y, a.y); m2.z = fmaxf(m2.z, a.z); m2.w = fmaxf(m2.w, a.w);
        a = __ldcs(p3 + o2); m3.x = fmaxf(m3.x, a.x); m3.y = fmaxf(m3.y, a.y); m3.z = fmaxf(m3.z, a.z); m3.w = fmaxf(m3.w, a.w);
        a = __ldcs(p0 + o3); m0.x = fmaxf(m0.x, a.x); m0.y = fmaxf(m0.y, a.y); m0.z = fmaxf(m0.z, a.z); m0.w = fmaxf(m0.w, a.w);
        a = __ldcs(p1 + o3); m1.x = fmaxf(m1.x, a.x); m1.y = fmaxf(m1.y, a.y); m1.z = fmaxf(m1.z, a.z); m1.w = fmaxf(m1.w, a.w);
        a = __ldcs(p2 + o3); m2.x = fmaxf(m2.x, a.x); m2.y = fmaxf(m2.y, a.y); m2.z = fmaxf(m2.z, a.z); m2.w = fmaxf(m2.w, a.w);
        a = __ldcs(p3 + o3); m3.x = fmaxf(m3.x, a.x); m3.y = fmaxf(m3.y, a.y); m3.z = fmaxf(m3.z, a.z); m3.w = fmaxf(m3.w, a.w);
    }
    for (; i < reduce; i += 8) {
        const size_t o = (size_t)i * inner4;
        float4 a;
        a = __ldcs(p0 + o); m0.x = fmaxf(m0.x, a.x); m0.y = fmaxf(m0.y, a.y); m0.z = fmaxf(m0.z, a.z); m0.w = fmaxf(m0.w, a.w);
        a = __ldcs(p1 + o); m1.x = fmaxf(m1.x, a.x); m1.y = fmaxf(m1.y, a.y); m1.z = fmaxf(m1.z, a.z); m1.w = fmaxf(m1.w, a.w);
        a = __ldcs(p2 + o); m2.x = fmaxf(m2.x, a.x); m2.y = fmaxf(m2.y, a.y); m2.z = fmaxf(m2.z, a.z); m2.w = fmaxf(m2.w, a.w);
        a = __ldcs(p3 + o); m3.x = fmaxf(m3.x, a.x); m3.y = fmaxf(m3.y, a.y); m3.z = fmaxf(m3.z, a.z); m3.w = fmaxf(m3.w, a.w);
    }
    if (!v0) m0 = ninf4;
    if (!v1) m1 = ninf4;
    if (!v2) m2 = ninf4;
    if (!v3) m3 = ninf4;
    partial4[warp][lane]      = m0;
    partial4[warp][lane + 32] = m1;
    partial4[warp][lane + 64] = m2;
    partial4[warp][lane + 96] = m3;
    __syncthreads();
    if (warp == 0) {
        #pragma unroll
        for (int k = 0; k < 4; ++k) {
            const int g = g0 + k * 32;
            if (g < inner4) {
                float4 r = partial4[0][lane + k * 32];
                #pragma unroll
                for (int w = 1; w < 8; ++w) {
                    const float4 s = partial4[w][lane + k * 32];
                    r.x = fmaxf(r.x, s.x);
                    r.y = fmaxf(r.y, s.y);
                    r.z = fmaxf(r.z, s.z);
                    r.w = fmaxf(r.w, s.w);
                }
                reinterpret_cast<float4*>(out + (size_t)b * inner)[g] = r;
            }
        }
    }
}
torch::Tensor max_reduce_middle(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    TORCH_CHECK(x.dim() == 3, "Input must be 3D");

    auto xc = x.contiguous();
    const int64_t d = (dim % 3 + 3) % 3;

    int64_t outer = 1, reduce = 1, inner = 1;
    for (int64_t k = 0; k < d; ++k) outer *= xc.size(k);
    reduce = xc.size(d);
    for (int64_t k = d + 1; k < 3; ++k) inner *= xc.size(k);

    std::vector<int64_t> out_sizes;
    for (int64_t k = 0; k < 3; ++k) {
        if (k != d) out_sizes.push_back(xc.size(k));
    }
    auto out = torch::empty(out_sizes, xc.options());

    if (outer == 0 || inner == 0) return out;
    if (reduce == 0) {
        out.fill_(-std::numeric_limits<float>::infinity());
        return out;
    }

    const int threads = 256;
    auto stream = at::cuda::getCurrentCUDAStream();
    if ((inner & 3) == 0) {
        const int inner4 = (int)(inner >> 2);
        dim3 grid4((unsigned)((inner4 + 127) / 128), (unsigned)outer);
        max_reduce_middle_vec4_kernel<<<grid4, threads, 0, stream>>>(
            xc.data_ptr<float>(),
            out.data_ptr<float>(),
            (int)outer, (int)reduce, (int)inner);
    } else {
        dim3 grid((unsigned)((inner + 127) / 128), (unsigned)outer);
        max_reduce_middle_kernel<<<grid, threads, 0, stream>>>(
            xc.data_ptr<float>(),
            out.data_ptr<float>(),
            (int)outer, (int)reduce, (int)inner);
    }

    return out;
}
"""

cpp_source = "torch::Tensor max_reduce_middle(torch::Tensor x, int64_t dim);"

_module = load_inline(
    name="max_reduce_middle_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["max_reduce_middle"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension using a custom CUDA kernel.
    """

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _module.max_reduce_middle(x, self.dim)

